// Combined validation and scoring
const data = $input.item.json;

// Validate
if (!data || !data.answers || !data.contact) {
  return {
    json: {
      status: "error",
      message: "Invalid payload - missing required fields",
      submissionId: data.submissionId || "unknown"
    }
  };
}

const answers = data.answers;
let score = 0;

// Q1: AI maturity
const q1Scores = { explorer: 10, experimenting: 30, scaling: 60, optimized: 80 };
score += q1Scores[answers.q1] || 0;

// Q3: Budget readiness
score += (answers.q3 || 0) * 5;

// Q4: Timeline
const q4Scores = { immediate: 20, '1-3 months': 15, '3-6 months': 10, '6+ months': 5 };
score += q4Scores[answers.q4] || 0;

// Q5: Decision authority
const q5Scores = { decision_maker: 15, influencer: 10, researcher: 5 };
score += q5Scores[answers.q5] || 0;

score = Math.min(score, 100);
const band = score >= 70 ? 'HIGH' : score >= 40 ? 'MEDIUM' : 'LOW';

return {
  json: {
    status: "success",
    submissionId: data.submissionId,
    contact: data.contact,
    score,
    band
  }
};
